#include <cstddef>

int main() {
    std::vector<int> ordenados{-5, -5, 2, 2, 2, 8};
    std::size_t coincidencias = 0;
    for (std::size_t i = 1; i < ordenados.size(); ++i) {
        if (ordenados[i] == ordenados[i - 1]) { ++coincidencias; }
    }
    std::cout << "Iguales al anterior:" << coincidencias
              << "\nN:" << ordenados.size() << "\n";
    return 0;
}

