#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <cstddef>

int main() {
    std::vector<std::string> original{"torre", "rio", "rio", "torre", "valle", "valle", "sol"};
    auto ordenadas = original;
    std::sort(ordenadas.begin(), ordenadas.end());
    std::size_t inicio = 0;
    std::size_t distintas = 0;
    std::size_t suma = 0;
    std::size_t maxima = 0;
    std::vector<std::string> mayores;
    std::cout << "Frecuencias:\n";
    while (inicio < ordenadas.size()) {
        std::size_t fin = inicio + 1;
        while (fin < ordenadas.size() && ordenadas[fin] == ordenadas[inicio]) {
            ++fin;
        }
        std::size_t frecuencia = fin - inicio;
        std::cout << "[" << ordenadas[inicio] << "]=" << frecuencia << "\n";
        ++distintas;
        suma += frecuencia;
        if (frecuencia > maxima) {
            maxima = frecuencia;
            mayores = std::vector<std::string>{};
            mayores.push_back(ordenadas[inicio]);
        } else if (frecuencia == maxima) {
            mayores.push_back(ordenadas[inicio]);
        }
        inicio = fin;
    }
    std::cout << "Maxima:" << maxima << "\nMayores:";
    for (const auto& etiqueta : mayores) { std::cout << "[" << etiqueta << "]"; }
    std::cout << "\nN:" << original.size() << "\nDistintas:" << distintas
              << "\nSuma:" << suma << "\nOriginal:";
    for (const auto& etiqueta : original) { std::cout << "[" << etiqueta << "]"; }
    std::cout << "\n";
    return 0;
}

